const BRAND = 'KIA';

function cleanText(v) {
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  if (!s || /^(nat|null|none|nan|undefined|-)$/.test(s.toLowerCase())) return null;
  return s;
}

function pick(d, keys) {
  for (const key of keys) {
    const v = cleanText(d[key]);
    if (v) return v;
  }
  return null;
}

function cleanPhone(v) {
  const s = cleanText(v);
  if (!s) return null;
  const normalized = s.replace(/\.0$/, '').replace(/[^\d+]/g, '');
  const digits = normalized.replace(/\D/g, '');
  return digits.length >= 7 ? normalized : null;
}

function cleanSendPhone(v) {
  const normalized = cleanPhone(v);
  if (!normalized) return null;
  const digits = normalized.replace(/\D/g, '');
  return digits.length >= 9 && digits.length <= 15 ? normalized : null;
}

function digitsOnly(v) {
  const s = cleanText(v);
  if (!s) return null;
  const digits = s.replace(/\D/g, '');
  return digits || null;
}

function truncateText(rowNumber, quicklinkId, field, value, maxLength, warnings) {
  const s = cleanText(value);
  if (!s) return null;
  if (s.length <= maxLength) return s;
  warnings.push(syncError(rowNumber, quicklinkId, field, 'value_truncated', s, maxLength));
  return s.slice(0, maxLength);
}

function parseDate(v) {
  return cleanText(v);
}

function fieldLength(v) {
  return v === undefined || v === null ? null : String(v).length;
}

function previewValue(v) {
  const s = cleanText(v);
  if (!s) return null;
  return `[redacted:${s.length}]`;
}

function syncError(rowNumber, quicklinkId, field, reason, value, valueLimit = null) {
  return {
    row_number: rowNumber,
    quicklink_id: Number.isInteger(quicklinkId) && quicklinkId > 0 ? quicklinkId : null,
    field,
    reason,
    value_length: fieldLength(value),
    value_limit: valueLimit,
    value_preview: previewValue(value)
  };
}

function skippedRow(rowNumber, quicklinkId, errors) {
  return { json: {
    quicklink_id: Number.isInteger(quicklinkId) && quicklinkId > 0 ? quicklinkId : null,
    marca: BRAND,
    nombre_cliente: null,
    ci_ruc: null,
    telefono_1: null,
    telefono_2: null,
    telefono_agente: null,
    correo_cliente: null,
    ciudad: null,
    chasis: null,
    modelo: null,
    clave_modelo: null,
    agencia: null,
    nombre_vendedor_ql: null,
    correo_vendedor_ql: null,
    fecha_venta: null,
    fecha_asignacion: null,
    fecha_gestion: null,
    fecha_final_gestion: null,
    estado_ql: null,
    observacion_ql: null,
    _skip_upsert: true,
    _sync_errors: errors
  } };
}

function lengthErrors(rowNumber, quicklinkId, lead) {
  const limits = { ci_ruc: 20, telefono_2: 20, telefono_agente: 256, chasis: 50 };
  const errors = [];
  for (const [field, maxLength] of Object.entries(limits)) {
    const value = lead[field];
    if (value !== null && value !== undefined && String(value).length > maxLength) {
      errors.push(syncError(rowNumber, quicklinkId, field, 'value_too_long', value, maxLength));
    }
  }
  return errors;
}

const rows = $input.all();
const invalidRows = [];
const validRows = [];
const skippedRows = [];
const duplicateRows = [];
const seenQuicklinkIds = new Set();
const seenIdentityKeys = new Set();

rows.forEach((item, index) => {
  const d = item.json || {};
  const rowNumber = index + 1;
  const idRaw = pick(d, ['ID', 'id', 'quicklink_id']);
  const quicklinkId = Number.parseInt(idRaw || '', 10);
  const nombre = pick(d, ['NOMBRE CLIENTE', 'nombre_cliente', 'nombre']);
  const ciRuc = pick(d, ['CI/RUC CLIENTE', 'CI RUC CLIENTE', 'ci_ruc']);
  const phone1Raw = pick(d, ['TELEFONO 1', 'TELÉFONO 1', 'telefono_1']);
  const phone2 = cleanPhone(pick(d, ['TELEFONO 2', 'TELÉFONO 2', 'telefono_2']));
  const agentPhoneRaw = pick(d, ['TELEFONO AGENTE', 'TELÉFONO AGENTE', 'telefono_agente']);
  const agentPhone = cleanSendPhone(agentPhoneRaw);
  const ciRucKey = digitsOnly(ciRuc);
  const agentPhoneKey = digitsOnly(agentPhone);
  const errors = [];
  const warnings = [];

  if (!Number.isInteger(quicklinkId) || quicklinkId <= 0) errors.push(syncError(rowNumber, null, 'quicklink_id', 'invalid_id', idRaw));
  if (!nombre) errors.push(syncError(rowNumber, quicklinkId, 'nombre_cliente', 'missing_name', nombre));
  if (!agentPhoneRaw) errors.push(syncError(rowNumber, quicklinkId, 'telefono_agente', 'missing_agent_phone', null));
  else if (!agentPhone) errors.push(syncError(rowNumber, quicklinkId, 'telefono_agente', 'invalid_agent_phone', agentPhoneRaw));

  if (errors.length) {
    invalidRows.push({ row: rowNumber, id: idRaw || null, reasons: errors.map(e => e.reason), errors });
    skippedRows.push(skippedRow(rowNumber, quicklinkId, errors));
    return;
  }

  if (seenQuicklinkIds.has(quicklinkId)) {
    const duplicateErrors = [syncError(rowNumber, quicklinkId, 'quicklink_id', 'duplicate_id', quicklinkId)];
    duplicateRows.push({ row: rowNumber, id: quicklinkId });
    skippedRows.push(skippedRow(rowNumber, quicklinkId, duplicateErrors));
    return;
  }
  seenQuicklinkIds.add(quicklinkId);

  const lead = {
    quicklink_id: quicklinkId,
    marca: BRAND,
    nombre_cliente: nombre,
    ci_ruc: ciRuc,
    telefono_1: truncateText(rowNumber, quicklinkId, 'telefono_1', phone1Raw, 256, warnings),
    telefono_2: phone2,
    telefono_agente: agentPhone,
    correo_cliente: pick(d, ['CORREO CLIENTE', 'correo_cliente']),
    ciudad: BRAND === 'HYUNDAI' ? pick(d, ['CIUDAD', 'ciudad']) : null,
    chasis: pick(d, ['CHASIS', 'chasis']),
    modelo: pick(d, ['MODELO', 'modelo']),
    clave_modelo: BRAND === 'HYUNDAI' ? pick(d, ['CLAVE_MODELO', 'CLAVE MODELO', 'clave_modelo']) : null,
    agencia: pick(d, ['AGENCIA', 'agencia']),
    nombre_vendedor_ql: pick(d, ['NOMBRE VENDEDOR QL', 'nombre_vendedor_ql']),
    correo_vendedor_ql: pick(d, ['CORREO VENDEDOR QL', 'correo_vendedor_ql']),
    fecha_venta: parseDate(pick(d, ['FECHA VENTA', 'fecha_venta'])),
    fecha_asignacion: parseDate(pick(d, ['FECHA ASIGNACION', 'FECHA ASIGNACIÓN', 'fecha_asignacion'])),
    fecha_gestion: parseDate(pick(d, ['FECHA GESTIÓN', 'FECHA GESTION', 'fecha_gestion'])),
    fecha_final_gestion: parseDate(pick(d, ['FECHA FINAL GESTIÓN', 'FECHA FINAL GESTION', 'fecha_final_gestion'])),
    estado_ql: pick(d, ['ESTADO', 'estado']) || 'NEW_LEAD',
    observacion_ql: pick(d, ['OBSERVACION', 'OBSERVACIÓN', 'observacion_ql']),
    ultima_sync_at: new Date().toISOString(),
    _sync_row_number: rowNumber
  };

  const schemaErrors = lengthErrors(rowNumber, quicklinkId, lead);
  if (schemaErrors.length) {
    invalidRows.push({ row: rowNumber, id: quicklinkId, reasons: schemaErrors.map(e => e.reason), errors: schemaErrors });
    skippedRows.push(skippedRow(rowNumber, quicklinkId, schemaErrors));
    return;
  }

  const identityKey = ciRucKey && agentPhoneKey ? `${ciRucKey}|${agentPhoneKey}` : null;
  if (identityKey && seenIdentityKeys.has(identityKey)) {
    const duplicateErrors = [syncError(rowNumber, quicklinkId, 'ci_ruc_telefono_agente', 'duplicate_cedula_agent_phone', identityKey)];
    duplicateRows.push({ row: rowNumber, id: quicklinkId, reason: 'duplicate_cedula_agent_phone' });
    skippedRows.push(skippedRow(rowNumber, quicklinkId, duplicateErrors));
    return;
  }
  if (identityKey) seenIdentityKeys.add(identityKey);

  if (warnings.length) lead._sync_errors = warnings;
  validRows.push({ json: lead });
});

const meta = {
  brand: BRAND,
  fetched: rows.length,
  valid: validRows.length,
  invalid: invalidRows.length,
  duplicates: duplicateRows.length,
  invalid_samples: invalidRows.slice(0, 5)
};

const outputRows = validRows.concat(skippedRows);

if (outputRows.length === 0) {
  return [{ json: {
    quicklink_id: null,
    marca: BRAND,
    nombre_cliente: null,
    ci_ruc: null,
    telefono_1: null,
    telefono_2: null,
    telefono_agente: null,
    correo_cliente: null,
    ciudad: null,
    chasis: null,
    modelo: null,
    clave_modelo: null,
    agencia: null,
    nombre_vendedor_ql: null,
    correo_vendedor_ql: null,
    fecha_venta: null,
    fecha_asignacion: null,
    fecha_gestion: null,
    fecha_final_gestion: null,
    estado_ql: null,
    observacion_ql: null,
    _skip_upsert: true,
    _sync_meta: meta
  } }];
}

return outputRows.map(item => ({
  json: {
    ...item.json,
    _sync_meta: meta
  }
}));

