function items(nodeName) {
  try { return $(nodeName).all(); } catch (e) { return []; }
}

function count(nodeName) {
  return items(nodeName).length;
}

function insertedCount(nodeName) {
  return items(nodeName).filter(item => item?.json?.inserted === true || String(item?.json?.inserted) === 'true').length;
}

function affectedCount(nodeName) {
  return items(nodeName).filter(item => item?.json?.affected === true || String(item?.json?.affected) === 'true' || item?.json?.inserted === true || String(item?.json?.inserted) === 'true').length;
}

function meta(nodeName) {
  try {
    const nodeItems = items(nodeName);
    return nodeItems[0]?.json?._sync_meta || { fetched: count(nodeName), valid: count(nodeName), invalid: 0, invalid_samples: [] };
  } catch (e) {
    return { fetched: 0, valid: 0, invalid: 0, invalid_samples: [] };
  }
}

const kiaMeta = meta('Transform KIA');
const hyundaiMeta = meta('Transform Hyundai');
const kiaInserted = insertedCount('Upsert KIA');
const hyundaiInserted = insertedCount('Upsert Hyundai');
const kiaAffected = affectedCount('Upsert KIA');
const hyundaiAffected = affectedCount('Upsert Hyundai');
const source = count('Webhook Sync Manual') > 0 ? 'manual' : 'scheduled';
const summary = {
  status: 'sync_ok',
  mode: 'refresh_existing',
  source,
  timestamp: new Date().toISOString(),
  kia_fetched: count('GET Leads KIA'),
  kia_valid: kiaMeta.valid,
  kia_invalid: kiaMeta.invalid,
  kia_inserted: kiaInserted,
  kia_refreshed: Math.max(kiaAffected - kiaInserted, 0),
  kia_existing_skipped: Math.max((kiaMeta.valid || 0) - kiaAffected, 0),
  kia_upserted: kiaAffected,
  hyundai_fetched: count('GET Leads Hyundai'),
  hyundai_valid: hyundaiMeta.valid,
  hyundai_invalid: hyundaiMeta.invalid,
  hyundai_inserted: hyundaiInserted,
  hyundai_refreshed: Math.max(hyundaiAffected - hyundaiInserted, 0),
  hyundai_existing_skipped: Math.max((hyundaiMeta.valid || 0) - hyundaiAffected, 0),
  hyundai_upserted: hyundaiAffected,
  invalid_samples: {
