if (summary.hyundai_invalid > 0) problems.push(`HYUNDAI invalid rows: ${summary.hyundai_invalid}`);
if (summary.kia_inserted > summary.kia_valid) problems.push(`KIA insert count invalid: valid=${summary.kia_valid} inserted=${summary.kia_inserted}`);
if (summary.hyundai_inserted > summary.hyundai_valid) problems.push(`HYUNDAI insert count invalid: valid=${summary.hyundai_valid} inserted=${summary.hyundai_inserted}`);

if (summary.kia_fetched === 0 && summary.hyundai_fetched === 0) {
  summary.status = 'sync_empty';
}

if (problems.length) {
  summary.status = 'sync_failed_validation';
  summary.error = problems.join('; ');
} else {
  summary.error = null;
}

return [{ json: summary }];

const query = $json.query || {};
const rawBrand = query.brand ?? query.marca ?? $json.brand ?? $json.marca ?? '';
const brand = String(rawBrand || '').trim().toLowerCase();
const allowedBrands = ['kia', 'hyundai'];

function intParam(value, fallback, min, max) {
  const n = Number.parseInt(value ?? '', 10);
  if (!Number.isInteger(n)) return fallback;
  return Math.min(Math.max(n, min), max);
}

const limit = intParam(query.limit ?? $json.limit, 100, 1, 500);
const offset = intParam(query.offset ?? $json.offset, 0, 0, 1000000);
const valid = allowedBrands.includes(brand);

if (!valid) {
  return [{ json: {
    valid: false,
    status: 'error',
    error: 'invalid_brand',
    message: 'Use brand=kia or brand=hyundai',
    allowed_brands: allowedBrands,
    received_brand: rawBrand || null
  } }];
}

const endpoint = `https://app.quicklink.com.ec:21305/api_kia/datos/${brand}/filtrados`;
const queryString = `limit=${encodeURIComponent(String(limit))}&offset=${encodeURIComponent(String(offset))}`;

return [{ json: {
  valid: true,
  status: 'ok',
  brand,
  limit,
  offset,
  endpoint,
  url: `${endpoint}?${queryString}`
} }];

