<script>
(function(){
  const DEFAULT_BASE = "https://quicklink.bkn.aigentss.cloud";
  const $ = id => document.getElementById(id);
  const LS = { token:"ql08_token", base:"ql08_base" };
  // localStorage puede lanzar SecurityError en documentos sandbox (webhook n8n): blindar.
  const store = {
    get(k){ try { return localStorage.getItem(k); } catch(e){ return null; } },
    set(k,v){ try { localStorage.setItem(k,v); } catch(e){} }
  };

  // ---- config load/save ----
  $("token").value = store.get(LS.token) || "__INJECT_TOKEN__";
  $("base").value  = store.get(LS.base)  || DEFAULT_BASE;
  $("saveCfg").onclick = () => {
    store.set(LS.token, $("token").value.trim());
    store.set(LS.base, ($("base").value.trim() || DEFAULT_BASE).replace(/\/+$/,""));
    flash($("syncMsg"),"ok","Configuración guardada.");
  };
  const persistToken = () => store.set(LS.token, $("token").value.trim());
  $("token").addEventListener("change", persistToken);

  const baseUrl = () => ($("base").value.trim() || DEFAULT_BASE).replace(/\/+$/,"");
  const token   = () => $("token").value.trim();

  function flash(el, kind, text, detail){
    el.className = "msg show " + kind;
    el.innerHTML = text + (detail ? "<pre>"+escapeHtml(detail)+"</pre>" : "");
  }
  function hide(el){ el.className = "msg"; el.innerHTML=""; }
  function escapeHtml(s){ return String(s).replace(/[&<>]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;"}[c])); }
  function corsHelp(e){
    return "No se pudo contactar el webhook. Causa más probable: CORS no está habilitado en el nodo webhook de n8n "+
           "(agregar Allowed Origins). También verifica la URL base y que el flujo esté activo.\n\nDetalle: "+ (e && e.message || e);
  }

  // ---- Sync manual (POST) ----
  $("btnSync").onclick = async () => {
    if(!token()){ flash($("syncMsg"),"warn","Falta el token de acceso."); return; }
    persistToken();
    const btn = $("btnSync"); btn.disabled = true; const old = btn.textContent;
    btn.innerHTML = '<span class="spin"></span>Ejecutando…';
    hide($("syncMsg")); $("syncStats").style.display = "none";
    try {
      const r = await fetch(baseUrl()+"/webhook/ql-sync-manual", {
        method:"POST",
        headers:{ "Content-Type":"application/json", "x-ql-sync-token": token() },
        body:"{}"
      });
      const raw = await r.text();
      let data = null; try { data = JSON.parse(raw); } catch(_){}
      if(!r.ok){ flash($("syncMsg"),"err","Error "+r.status+" al ejecutar el sync.", raw.slice(0,600)); return; }
      // onReceived puede devolver vacío; mostramos lo que haya
      const s = (data && (data.summary || data)) || {};
      const kf = pick(s,"kia_fetched"), hf = pick(s,"hyundai_fetched");
      const up = num(pick(s,"kia_upserted")) + num(pick(s,"hyundai_upserted"));
      const inv = num(pick(s,"kia_invalid")) + num(pick(s,"hyundai_invalid"));
      if(kf!=null || hf!=null){
        $("s-kf").textContent  = fmt(kf);
        $("s-hf").textContent  = fmt(hf);
        $("s-up").textContent  = fmt(up);
        $("s-inv").textContent = fmt(inv);
        $("syncStats").style.display = "grid";
        flash($("syncMsg"),"ok","Sync ejecutado.");
        loadHistory();
        loadErrors();
      } else {
        flash($("syncMsg"),"ok","Sync disparado. Corriendo en segundo plano; el histórico se actualizará en unos segundos.");
        setTimeout(loadHistory, 8000);
        setTimeout(loadHistory, 18000);
        setTimeout(loadErrors, 18000);
      }
    } catch(e){
      flash($("syncMsg"),"err", corsHelp(e));
    } finally { btn.disabled=false; btn.textContent = old; }
  };

  // ---- Consulta por marca (GET) ----
  let lastRows = [], lastBrand = "";
  const clampInt = (v,min,max,def) => { let n=parseInt(v,10); if(!Number.isInteger(n)) n=def; return Math.min(Math.max(n,min),max); };

  async function runQuery(){
    if(!token()){ flash($("getMsg"),"warn","Falta el token de acceso."); return; }
    persistToken();
    const brand = $("brand").value;
    const limit = clampInt($("limit").value,1,500,100);
    const offset= clampInt($("offset").value,0,1000000,0);
    $("limit").value=limit; $("offset").value=offset;
    const btn=$("btnGet"); btn.disabled=true; const old=btn.textContent; btn.innerHTML='<span class="spin"></span>';
    hide($("getMsg"));
    try {
      const url = baseUrl()+"/webhook/ql-get-by-brand?brand="+encodeURIComponent(brand)+"&limit="+limit+"&offset="+offset;
      const r = await fetch(url, { method:"GET", headers:{ "x-ql-sync-token": token() } });
      const raw = await r.text();
      let data=null; try{ data=JSON.parse(raw);}catch(_){}
      if(!r.ok){ flash($("getMsg"),"err","Error "+r.status+" en la consulta.", raw.slice(0,600)); $("results").style.display="none"; return; }
      if(data && data.status==="error"){ flash($("getMsg"),"warn", (data.message||"Solicitud inválida.")+" ("+(data.received_brand||"")+")"); $("results").style.display="none"; return; }
      const rows = (data && data.data) || [];
      lastRows = rows; lastBrand = brand;
      renderTable(rows);
      $("getMeta").textContent = rows.length+" filas · marca "+brand+" · límite "+limit+" · offset "+offset;
      $("results").style.display = rows.length ? "block" : "block";
      if(!rows.length) flash($("getMsg"),"warn","Sin resultados para esos parámetros.");
    } catch(e){
      flash($("getMsg"),"err", corsHelp(e)); $("results").style.display="none";
    } finally { btn.disabled=false; btn.textContent=old; }
  }
  $("btnGet").onclick = runQuery;

  const PREF = ["telefono","phone","nombre","name","nombres","modelo","model","vehiculo","marca","brand","ciudad","city","placa","email","correo"];
  function columns(rows){
    const seen = new Set();
    rows.forEach(r => Object.keys(r||{}).forEach(k=>seen.add(k)));
    const all = [...seen];
    const ordered = PREF.filter(k=>seen.has(k)).concat(all.filter(k=>!PREF.includes(k)));
    return ordered.slice(0,10);
  }
  function renderTable(rows){
    const cols = columns(rows);
    $("thead").innerHTML = "<tr>"+cols.map(c=>"<th>"+escapeHtml(c)+"</th>").join("")+"</tr>";
    $("tbody").innerHTML = rows.map(r=>"<tr>"+cols.map(c=>{
      let v=r?r[c]:""; if(v==null)v=""; if(typeof v==="object")v=JSON.stringify(v);
      return "<td>"+escapeHtml(String(v))+"</td>";
    }).join("")+"</tr>").join("");
  }

  $("prev").onclick = () => { const l=clampInt($("limit").value,1,500,100); const o=clampInt($("offset").value,0,1e9,0); $("offset").value=Math.max(0,o-l); runQuery(); };
  $("next").onclick = () => { const l=clampInt($("limit").value,1,500,100); const o=clampInt($("offset").value,0,1e9,0); $("offset").value=o+l; runQuery(); };

  $("csv").onclick = () => {
    if(!lastRows.length) return;
    const cols = columns(lastRows);
    const esc = v => { if(v==null)v=""; if(typeof v==="object")v=JSON.stringify(v); v=String(v); return /[",\n]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v; };
    const csv = [cols.join(",")].concat(lastRows.map(r=>cols.map(c=>esc(r?r[c]:"")).join(","))).join("\n");
    const blob = new Blob([csv],{type:"text/csv;charset=utf-8"});
    const a=document.createElement("a"); a.href=URL.createObjectURL(blob);
    a.download="leads_"+lastBrand+"_"+new Date().toISOString().slice(0,10)+".csv"; a.click();
  };

  // ---- Histórico (GET ql-sync-history) ----
  const ORIGEN = { scheduled:"09:30 (auto)", manual:"Manual" };
  const ESTADO = {
    sync_ok:{t:"OK",c:"var(--ok)"}, sync_empty:{t:"Vacío",c:"var(--warn)"},
    sync_failed_validation:{t:"Falló",c:"var(--err)"}
  };
  function fmtDate(iso){
    if(!iso) return "–";
    const d = new Date(iso); if(isNaN(d)) return iso;
    return d.toLocaleString("es-EC",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"});
  }
  async function loadHistory(){
    if(!token()){ flash($("histMsg"),"warn","Falta el token de acceso."); return; }
    const limit = clampInt($("histLimit").value,1,200,30); $("histLimit").value=limit;
    const btn=$("btnHist"); btn.disabled=true; const old=btn.textContent; btn.innerHTML='<span class="spin"></span>';
    hide($("histMsg"));
    try {
      const r = await fetch(baseUrl()+"/webhook/ql-sync-history?limit="+limit, { method:"GET", headers:{ "x-ql-sync-token": token() } });
      const raw = await r.text(); let data=null; try{ data=JSON.parse(raw);}catch(_){}
      if(!r.ok){ flash($("histMsg"),"err","Error "+r.status+" al leer el histórico.", raw.slice(0,500)); $("histResults").style.display="none"; return; }
      const rows = (data && data.data) || [];
      if(!rows.length){ $("histResults").style.display="none"; flash($("histMsg"),"warn","Aún no hay corridas registradas. Ejecuta un sync o espera la corrida de las 09:30."); return; }
      $("histBody").innerHTML = rows.map(x=>{
        const est = ESTADO[x.status] || {t:x.status,c:"var(--muted)"};
        const org = ORIGEN[x.source] || x.source || "–";
        return "<tr>"+
          "<td>"+escapeHtml(fmtDate(x.run_at))+"</td>"+
          "<td>"+escapeHtml(org)+"</td>"+
          "<td><span style='color:"+est.c+"'>&#9679; "+escapeHtml(est.t)+"</span></td>"+
          "<td>"+num(x.kia_fetched)+" &rarr; "+num(x.kia_upserted)+"</td>"+
          "<td>"+num(x.hyundai_fetched)+" &rarr; "+num(x.hyundai_upserted)+"</td>"+
          "<td>"+(num(x.kia_invalid)+num(x.hyundai_invalid))+"</td>"+
        "</tr>";
      }).join("");
      $("histResults").style.display="block";
      $("histMeta").textContent = rows.length+" corridas · más reciente arriba";
    } catch(e){ flash($("histMsg"),"err", corsHelp(e)); $("histResults").style.display="none"; }
    finally { btn.disabled=false; btn.textContent=old; }
  }
  $("btnHist").onclick = loadHistory;


  // ---- Errores omitidos (GET ql-sync-errors) ----
  async function loadErrors(){
    if(!token()){ flash($("errMsg"),"warn","Falta el token de acceso."); return; }
    const limit = clampInt($("errLimit").value,1,500,100); $("errLimit").value=limit;
    const runId = $("errRun").value.trim();
    const brand = $("errBrand").value;
    const qs = new URLSearchParams({ limit:String(limit) });
    if(runId) qs.set("sync_run_id", runId);
    if(brand) qs.set("brand", brand);
    const btn=$("btnErrors"); btn.disabled=true; const old=btn.textContent; btn.innerHTML='<span class="spin"></span>';
    hide($("errMsg"));
    try {
      const r = await fetch(baseUrl()+"/webhook/ql-sync-errors?"+qs.toString(), { method:"GET", headers:{ "x-ql-sync-token": token() } });
      const raw = await r.text(); let data=null; try{ data=JSON.parse(raw);}catch(_){ }
      if(!r.ok){ flash($("errMsg"),"err","Error "+r.status+" al leer errores.", raw.slice(0,500)); $("errResults").style.display="none"; return; }
      const rows = (data && data.data) || [];
