const run = $input.first()?.json || {};

function items(nodeName) {
  try { return $(nodeName).all(); } catch (e) { return []; }
}

function errorRows(nodeName, brand) {
  const rows = [];
  for (const item of items(nodeName)) {
    const json = item?.json || {};
    let errors = Array.isArray(json._sync_errors) ? json._sync_errors : [];
    if (!errors.length && typeof json._sync_errors === 'string') {
      try {
        const parsed = JSON.parse(json._sync_errors);
        errors = Array.isArray(parsed) ? parsed : [];
      } catch (e) {
        errors = [];
      }
    }
    for (const err of errors) {
      rows.push({ json: {
        sync_run_id: run.sync_run_id || null,
        run_at: run.timestamp || new Date().toISOString(),
        source: run.source || 'scheduled',
        marca: err.marca || json.marca || brand,
        quicklink_id: err.quicklink_id ?? json.quicklink_id ?? null,
        row_number: err.row_number ?? null,
        field: err.field || 'row',
        reason: err.reason || 'invalid_row',
        value_length: err.value_length ?? null,
        value_limit: err.value_limit ?? null,
        value_preview: err.value_preview ?? null
      } });
    }
  }
  return rows;
}

